BEGIN;
ALTER TABLE public.redirects DROP CONSTRAINT redirects_pending_tenant_fence;
ALTER TABLE public.redirect_events DROP CONSTRAINT redirect_events_pending_tenant_fence;
ALTER TABLE public.redirect_domains DROP CONSTRAINT redirect_domains_pending_tenant_fence;
ALTER TABLE public.redirect_domain_jobs DROP CONSTRAINT redirect_domain_jobs_pending_tenant_fence;
ALTER TABLE public.redirect_password_attempts DROP CONSTRAINT redirect_password_attempts_pending_tenant_fence;
ALTER TABLE public.redirect_password_branding DROP CONSTRAINT redirect_password_branding_pending_tenant_fence;
DO $$ DECLARE fence text; BEGIN
 SELECT conname INTO fence FROM pg_constraint WHERE conrelid='public.redirect_workspaces'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%status%provisioning%is_legacy%';
 IF fence IS NULL THEN RAISE EXCEPTION 'Missing activation fixture fence';END IF;
 EXECUTE format('ALTER TABLE public.redirect_workspaces DROP CONSTRAINT %I',fence);
END $$;
SET LOCAL ROLE service_role;
DO $$
DECLARE legacy uuid:='58aa4340-8f21-4b7f-9a10-90be2da89c01';other uuid:=gen_random_uuid();actor uuid:=gen_random_uuid();owner uuid:=gen_random_uuid();domain uuid:=gen_random_uuid();provider text:=gen_random_uuid()::text;builtin uuid;custom uuid;root_link uuid;local_link uuid;s jsonb;click uuid;before_count integer;
BEGIN
 INSERT INTO auth.users(id) VALUES(actor),(owner);INSERT INTO public.user_roles VALUES(actor,'admin');
 INSERT INTO public.redirect_workspaces(id,name,slug) VALUES(other,'Public link identity','public-link-identity');
 INSERT INTO redirect_internal.workspace_owners(workspace_id,user_id) VALUES(other,owner),(other,actor);
 INSERT INTO public.redirects(workspace_id,type,slug,target) VALUES(other,'SHORT','future-public-builtin','https://example.org/future-builtin') RETURNING id INTO builtin;
 INSERT INTO public.redirects(type,slug,target) VALUES('SHORT','local-public-builtin','https://example.org/local') RETURNING id INTO local_link;
 INSERT INTO public.redirect_domains(id,workspace_id,hostname,created_by,provider_id,ownership_state,verified_at,verified_until,routing_provider_id,routing_protocol,routing_seen_at) VALUES(domain,other,'public-link-identity.example.org',owner,provider,'verified',now(),now()+interval '3 hours',provider,1,now());
 INSERT INTO public.redirect_domain_jobs(workspace_id,domain_id,zone_id,cname_target,requested_by,state,provider_status,ssl_status,checked_at,create_nonce) VALUES(other,domain,repeat('a',32),'links.queer.guide',owner,'ready','active','active',now(),gen_random_uuid());
 IF public.redirect_resolution_snapshot('queer.guide','future-public-builtin') IS NOT NULL OR public.redirect_public_domain('public-link-identity.example.org') IS NOT NULL OR redirect_internal.public_link_workspace(builtin,'queer.guide') IS NOT NULL THEN RAISE EXCEPTION 'Provisioning workspace became publicly routable';END IF;
 UPDATE public.redirect_workspaces SET status='active' WHERE id=other;
 INSERT INTO public.redirect_password_branding(workspace_id,link_id,brand_name) VALUES(other,builtin,'Future workspace brand');
 IF public.redirect_password_branding_public(builtin)->>'brandName'<>'Future workspace brand' THEN RAISE EXCEPTION 'Public password branding lost source workspace';END IF;
 IF public.reserve_redirect_password_attempt(builtin,repeat('a',64))<>0 THEN RAISE EXCEPTION 'Public password budget unexpectedly throttled';END IF;
 IF NOT EXISTS(SELECT FROM public.redirect_password_attempts WHERE workspace_id=other AND redirect_id=builtin) THEN RAISE EXCEPTION 'Public password budget lost source workspace';END IF;
 INSERT INTO public.redirects(workspace_id,type,slug,target,domain_id) VALUES(other,'SHORT','custom-public-link','https://example.org/future-custom',domain) RETURNING id INTO custom;
 INSERT INTO public.redirects(workspace_id,type,slug,target,domain_id,is_domain_root) VALUES(other,'SHORT','internal-root-identity','https://example.org/future-root',domain,true) RETURNING id INTO root_link;
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-workspace',legacy,'x-qg-redirect-session-actor',actor)::text,true);
 s:=public.redirect_resolution_snapshot('queer.guide','future-public-builtin');
 IF s#>>'{link,id}'<>builtin::text OR s#>>'{link,workspace_id}'<>other::text OR public.redirect_resolution_snapshot('www.queer.guide','future-public-builtin') IS DISTINCT FROM s THEN RAISE EXCEPTION 'Global built-in slug did not derive resource workspace';END IF;
 click:=public.record_redirect_snapshot_visit(s->>'fingerprint',builtin,'/go/future-public-builtin',NULL,NULL,NULL,'CH',NULL,302,NULL,'https://example.org/future-builtin','{"domain":"queer.guide"}');
 IF click IS NULL OR NOT EXISTS(SELECT FROM public.redirect_events WHERE click_id=click AND workspace_id=other) THEN RAISE EXCEPTION 'Built-in visit lost resource workspace';END IF;
 s:=public.redirect_resolution_snapshot('public-link-identity.example.org','custom-public-link');
 IF s#>>'{link,id}'<>custom::text OR public.redirect_public_workspace('public-link-identity.example.org') IS DISTINCT FROM other THEN RAISE EXCEPTION 'Custom hostname did not derive resource workspace';END IF;
 IF NOT public.record_redirect_domain_route('public-link-identity.example.org') THEN RAISE EXCEPTION 'Active hostname route proof did not refresh';END IF;
 click:=public.record_redirect_snapshot_visit(s->>'fingerprint',custom,'/custom-public-link',NULL,NULL,NULL,'CH',NULL,302,NULL,'https://example.org/future-custom','{"domain":"public-link-identity.example.org"}');
 IF click IS NULL OR NOT EXISTS(SELECT FROM public.redirect_events WHERE click_id=click AND workspace_id=other) THEN RAISE EXCEPTION 'Custom visit lost resource workspace';END IF;
 IF public.record_redirect_snapshot_visit(s->>'fingerprint',custom,'/custom-public-link',NULL,NULL,NULL,NULL,NULL,302,NULL,'https://example.org/future-custom','{"domain":"queer.guide"}') IS NOT NULL OR redirect_internal.public_link_workspace(local_link,'public-link-identity.example.org') IS NOT NULL OR public.redirect_resolution_snapshot('queer.guide','custom-public-link') IS NOT NULL THEN RAISE EXCEPTION 'Public link crossed host namespace';END IF;
 s:=public.redirect_resolution_snapshot('public-link-identity.example.org',NULL,true);
 IF s#>>'{link,id}'<>root_link::text OR public.redirect_resolution_snapshot('public-link-identity.example.org','internal-root-identity') IS NOT NULL THEN RAISE EXCEPTION 'Custom root identity lost or internal slug exposed';END IF;
 click:=public.record_redirect_snapshot_visit(s->>'fingerprint',root_link,'/',NULL,NULL,NULL,'CH',NULL,302,NULL,'https://example.org/future-root','{"domain":"public-link-identity.example.org"}');
 IF click IS NULL THEN RAISE EXCEPTION 'Custom root visit denied';END IF;
 SELECT count(*) INTO before_count FROM public.redirect_events;
 UPDATE public.redirect_workspaces SET status='provisioning' WHERE id=other;
 IF public.redirect_password_branding_public(builtin) IS NOT NULL OR public.record_redirect_domain_route('public-link-identity.example.org') THEN RAISE EXCEPTION 'Inactive public password/route authority survived';END IF;
 BEGIN PERFORM public.reserve_redirect_password_attempt(builtin,repeat('b',64));RAISE EXCEPTION 'Inactive public password budget reserved';EXCEPTION WHEN no_data_found THEN NULL;END;
 IF public.redirect_resolution_snapshot('queer.guide','future-public-builtin') IS NOT NULL OR public.redirect_public_domain('public-link-identity.example.org') IS NOT NULL OR public.record_redirect_visit(builtin,'/go/future-public-builtin',NULL,NULL,NULL,NULL,NULL,302,NULL,'https://example.org/future-builtin','{}') IS NOT NULL THEN RAISE EXCEPTION 'Inactive workspace retained public routing/visits';END IF;
 UPDATE public.redirect_workspaces SET status='active' WHERE id=other;
 UPDATE redirect_internal.workspace_owners SET active=false WHERE workspace_id=other AND user_id=owner;
 IF public.redirect_public_domain('public-link-identity.example.org') IS NOT NULL OR public.redirect_resolution_snapshot('public-link-identity.example.org','custom-public-link') IS NOT NULL THEN RAISE EXCEPTION 'Provider requester lost authority but hostname remained ready';END IF;
 IF (SELECT count(*) FROM public.redirect_events)<>before_count OR (SELECT click_count FROM public.redirects WHERE id=builtin)<>1 OR (SELECT click_count FROM public.redirects WHERE id=custom)<>1 OR (SELECT click_count FROM public.redirects WHERE id=root_link)<>1 THEN RAISE EXCEPTION 'Denied routing inflated visits';END IF;
 PERFORM set_config('request.headers',jsonb_build_object('x-qg-redirect-workspace',other,'x-qg-redirect-session-actor',actor)::text,true);
 IF public.redirect_management_scope(NULL,'links:read') IS NOT NULL THEN RAISE EXCEPTION 'Current active explicit Owner lost workspace scope';END IF;
 IF has_function_privilege('anon','redirect_internal.public_link_workspace(uuid,text)','execute') OR has_function_privilege('authenticated','redirect_internal.public_link_workspace(uuid,text)','execute') THEN RAISE EXCEPTION 'Public resource helper exposed through Data API';END IF;
END $$;
ROLLBACK;
